#!/usr/bin/env python3
"""
Builds assets/stats-section.svg  ->  GitHub Stats + Contribution Streak + Most Used Languages
in the same neon style as your profile card, using REAL GitHub data.

Run by GitHub Action. Needs only:  pip install fonttools   (fonts are embedded below).
If GitHub can't be reached the old image is kept - nothing is ever faked.
"""
import os, sys, io, json, base64, random, datetime as dt, urllib.request
from pathlib import Path
from fontTools.ttLib import TTFont
from fontTools.pens.svgPathPen import SVGPathPen

USERNAME = "sskksingh2005"
OUT = Path(__file__).resolve().parent / "assets" / "stats-section.svg"
EXCLUDE_LANGS = []          # e.g. ["Jupyter Notebook"] to hide a language from the bar
MAX_LANGS = 6

FONT_DATA = {"B": "", "M": "", "R": ""}       # Poppins Bold / Medium / Regular (ASCII subset, SIL OFL)

PANEL2, BLUE, CYAN, PURPLE = "#0B1832", "#247BFF", "#00D9FF", "#8B5CFF"
TXT, MUTED = "#F4F7FF", "#AAB8D0"
BORDER = "rgba(56,189,248,0.38)"

# ---------------------------------------------------------------- text -> paths
_f, _g = {}, {}
def _font(k):
    if k not in _f:
        t = TTFont(io.BytesIO(base64.b64decode(FONT_DATA[k])))
        _f[k] = (t.getGlyphSet(), t.getBestCmap(), t["head"].unitsPerEm)
    return _f[k]
def _glyph(k, ch):
    if (k, ch) not in _g:
        gs, cm, upm = _font(k)
        n = cm.get(ord(ch)) or cm.get(ord("?"))
        pen = SVGPathPen(gs); gs[n].draw(pen)
        _g[(k, ch)] = (pen.getCommands(), gs[n].width / upm)
    return _g[(k, ch)]
def measure(txt, k, size):
    return sum(_glyph(k, c)[1] * size for c in txt)
def text(txt, k, size, x, y, fill, anchor="s"):
    w = measure(txt, k, size)
    x = x - w / 2 if anchor == "m" else x - w if anchor == "e" else x
    sc = size / _font(k)[2]; parts = []
    for c in txt:
        d, adv = _glyph(k, c)
        if d: parts.append(f'<path transform="translate({x:.1f},{y:.1f}) scale({sc:.5f},{-sc:.5f})" d="{d}"/>')
        x += adv * size
    return f'<g fill="{fill}">{"".join(parts)}</g>'

# ---------------------------------------------------------------- icons
GH = ("M12 .297c-6.63 0-12 5.373-12 12 0 5.303 3.438 9.8 8.205 11.385.6.113.82-.258.82-.577 0-.285-.01-1.04-.015-2.04-3.338.724-4.042-1.61-4.042-1.61C4.422 18.07 3.633 17.7 3.633 17.7c-1.087-.744.084-.729.084-.729 1.205.084 1.838 1.236 1.838 1.236 1.07 1.835 2.809 1.305 3.495.998.108-.776.417-1.305.76-1.605-2.665-.3-5.466-1.332-5.466-5.93 0-1.31.465-2.38 1.235-3.22-.135-.303-.54-1.523.105-3.176 0 0 1.005-.322 3.3 1.23.96-.267 1.98-.399 3-.405 1.02.006 2.04.138 3 .405 2.28-1.552 3.285-1.23 3.285-1.23.645 1.653.24 2.873.12 3.176.765.84 1.23 1.91 1.23 3.22 0 4.61-2.805 5.625-5.475 5.92.42.36.81 1.096.81 2.22 0 1.606-.015 2.896-.015 3.286 0 .315.21.69.825.57C20.565 22.092 24 17.592 24 12.297c0-6.627-5.373-12-12-12")
ICONS = {
    "commit": '<circle r="3.6"/><path d="M-9 0h5.4M3.6 0H9"/>',
    "repo": '<rect x="-6" y="-8" width="12" height="16" rx="2"/><path d="M-6 3h12M-2 -4h4"/>',
    "star": '<path d="M0 -8L2.3 -2.6 8 -2 3.6 1.8 4.9 7.4 0 4.4 -4.9 7.4 -3.6 1.8 -8 -2 -2.3 -2.6Z"/>',
    "users": '<circle cx="-3" cy="-3" r="3"/><path d="M-9 7c0-3 2.7-5 6-5s6 2 6 5"/><circle cx="5" cy="-2" r="2.4"/><path d="M5 2.5c2.5 0 4.5 1.4 4.5 4"/>',
    "userplus": '<circle cx="-2" cy="-3" r="3.2"/><path d="M-8.5 7c0-3 2.8-5 6.5-5s6.5 2 6.5 5"/><path d="M7 -5v6M4 -2h6"/>',
    "code": '<path d="M-4 -5L-9 0l5 5M4 -5l5 5-5 5M1.5 -7l-3 14"/>',
}
FLAME = '<path d="M0 -9C1 -4 6 -2 6 3A6 6 0 0 1 -6 3C-6 0 -4 -2 -3 -4C-2 -2 -1 -2 -.5 -3C0 -5 0 -7 0 -9Z"/>'
def ic(n, x, y, c, s=1.0):
    return f'<g transform="translate({x:.1f},{y:.1f}) scale({s})" fill="none" stroke="{c}" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">{ICONS[n]}</g>'

# ---------------------------------------------------------------- data
def gql(query, token):
    req = urllib.request.Request("https://api.github.com/graphql", data=json.dumps({"query": query}).encode(),
        headers={"Authorization": f"bearer {token}", "User-Agent": "stats-section", "Content-Type": "application/json"})
    with urllib.request.urlopen(req, timeout=40) as r:
        out = json.loads(r.read().decode())
    if out.get("data") is None:
        raise RuntimeError(f"GraphQL error: {out.get('errors')}")
    return out["data"]

def fetch():
    token = os.environ.get("GITHUB_TOKEN") or os.environ.get("GH_TOKEN")
    if not token: raise RuntimeError("no token in environment")
    now = dt.datetime.now(dt.timezone.utc)
    u = gql(f'''{{ user(login:"{USERNAME}") {{ createdAt followers {{ totalCount }} following {{ totalCount }}
        all: repositories(privacy: PUBLIC, ownerAffiliations: OWNER) {{ totalCount }}
        own: repositories(privacy: PUBLIC, ownerAffiliations: OWNER, isFork: false, first: 100) {{
            nodes {{ stargazerCount languages(first: 10, orderBy: {{field: SIZE, direction: DESC}}) {{ edges {{ size node {{ name color }} }} }} }} }} }} }}''', token)["user"]
    stars = sum(n["stargazerCount"] for n in u["own"]["nodes"])
    langs = {}
    for n in u["own"]["nodes"]:
        for e in n["languages"]["edges"]:
            nm = e["node"]["name"]
            if nm in EXCLUDE_LANGS: continue
            cur = langs.setdefault(nm, [0, e["node"]["color"] or "#8b949e"]); cur[0] += e["size"]
    top = sorted(langs.items(), key=lambda kv: -kv[1][0])[:MAX_LANGS]
    tot = sum(v[0] for _, v in top) or 1
    langs = [(k, v[0] / tot * 100, v[1]) for k, v in top]
    parts = []
    for y in range(int(u["createdAt"][:4]), now.year + 1):
        to = now.strftime("%Y-%m-%dT%H:%M:%SZ") if y == now.year else f"{y}-12-31T23:59:59Z"
        parts.append(f'y{y}: contributionsCollection(from:"{y}-01-01T00:00:00Z", to:"{to}") {{ totalCommitContributions '
                     f'restrictedContributionsCount contributionCalendar {{ weeks {{ contributionDays {{ date contributionCount }} }} }} }}')
    cc = gql(f'{{ user(login:"{USERNAME}") {{ {" ".join(parts)} }} }}', token)["user"]
    commits, days = 0, {}
    for col in cc.values():
        commits += col["totalCommitContributions"] + col["restrictedContributionsCount"]
        for w in col["contributionCalendar"]["weeks"]:
            for d in w["contributionDays"]:
                days[dt.date.fromisoformat(d["date"])] = d["contributionCount"]
    return dict(commits=commits, repos=u["all"]["totalCount"], stars=stars, followers=u["followers"]["totalCount"],
                following=u["following"]["totalCount"], days=days, langs=langs, updated=now.strftime("%d %b %Y"))

def streak_info(days):
    today = dt.datetime.now(dt.timezone.utc).date(); one = dt.timedelta(days=1)
    best = (0, None, None); run = 0; start = None
    for d in sorted(days):
        if days[d] > 0:
            if run == 0: start = d
            run += 1
            if run > best[0]: best = (run, start, d)
        else:
            run = 0
    end = today if days.get(today, 0) > 0 else today - one
    cur, s = 0, None
    d = end
    while days.get(d, 0) > 0:
        cur += 1; s = d; d -= one
    total = sum(c for dd, c in days.items() if today - dt.timedelta(days=364) <= dd <= today)
    return dict(cur=cur, cur_range=(s, end), best=best[0], best_range=(best[1], best[2]), total=total, today=today)

def rng(a, b, today):
    if not a: return "-"
    f = lambda d: d.strftime("%b %d").replace(" 0", " ")
    return f"{f(a)} - {'Present' if b == today else f(b)}"

def mock():  # layout preview only - never written to the real file
    r = random.Random(4); today = dt.datetime.now(dt.timezone.utc).date()
    return dict(commits=1234, repos=28, stars=42, followers=250, following=40, updated=today.strftime("%d %b %Y"),
        days={today - dt.timedelta(days=i): (0 if i > 41 and r.random() < .3 else r.choice([1, 2, 4, 7])) for i in range(900)},
        langs=[("TypeScript", 41.2, "#3178c6"), ("Python", 24.5, "#3572A5"), ("JavaScript", 14.1, "#f1e05a"), ("Java", 10.3, "#b07219"), ("HTML", 6.1, "#e34c26"), ("CSS", 3.8, "#563d7c")])

# ---------------------------------------------------------------- render
W, H = 1100, 280
def render(d):
    o = [f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 {W} {H}" width="{W}" height="{H}">',
         '<title>GitHub stats, contribution streak and most used languages for sskksingh2005</title>',
         f'''<defs><filter id="glow" x="-40%" y="-40%" width="180%" height="180%"><feGaussianBlur stdDeviation="3" result="b"/><feMerge><feMergeNode in="b"/><feMergeNode in="SourceGraphic"/></feMerge></filter>
<linearGradient id="pg" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#050b22"/><stop offset=".62" stop-color="#0a1538"/><stop offset="1" stop-color="#150f3d"/></linearGradient>
<radialGradient id="gp"><stop offset="0" stop-color="{PURPLE}" stop-opacity=".30"/><stop offset="1" stop-color="{PURPLE}" stop-opacity="0"/></radialGradient>
<radialGradient id="gb"><stop offset="0" stop-color="{BLUE}" stop-opacity=".30"/><stop offset="1" stop-color="{BLUE}" stop-opacity="0"/></radialGradient>
<clipPath id="barclip"><rect x="34" y="62" width="1032" height="14" rx="7"/></clipPath>
<style>.pn{{opacity:0;animation:fi .7s ease forwards}}@keyframes fi{{to{{opacity:1}}}}
.st{{animation:tw 4s ease-in-out infinite}}@keyframes tw{{0%,100%{{opacity:.1}}50%{{opacity:.85}}}}
.gx{{transform-box:fill-box;transform-origin:0 50%;animation:gx 1.2s cubic-bezier(.2,.8,.2,1) both}}@keyframes gx{{from{{transform:scaleX(0)}}to{{transform:scaleX(1)}}}}
.fl{{transform-box:fill-box;transform-origin:50% 100%;animation:fl 2.6s ease-in-out infinite}}@keyframes fl{{0%,100%{{transform:scale(1)}}50%{{transform:scale(1.08,1.12)}}}}
@media (prefers-reduced-motion: reduce){{*{{animation:none!important}}.pn{{opacity:1}}}}</style></defs>''']
    rnd = random.Random(5)
    def panel(x, y, w, h, delay, inner):
        stars = "".join(f'<circle class="st" cx="{x+rnd.uniform(14,w-14):.0f}" cy="{y+rnd.uniform(10,h-10):.0f}" r="{rnd.choice([.7,1,1.3])}" fill="#fff" style="animation-delay:{rnd.uniform(0,4):.1f}s"/>' for _ in range(int(w/22)))
        return (f'<g class="pn" style="animation-delay:{delay}s"><rect x="{x}" y="{y}" width="{w}" height="{h}" rx="22" fill="url(#pg)" stroke="{BORDER}" stroke-width="1.4"/>'
                f'<circle cx="{x+w-60}" cy="{y+h-20}" r="150" fill="url(#gp)"/>{stars}{inner}</g>')
    dash = "-"
    # ================= GitHub Stats
    cap = f"public data - updated {d['updated']}" if d else "data unavailable"
    s = [f'<g transform="translate(40,38) scale(.9) translate(-12,-12)" fill="{TXT}"><path d="{GH}"/></g>',
         text("GitHub Stats", "B", 17, 62, 44, TXT), text(cap, "R", 11.5, 10 + 700 - 22, 43, MUTED, "e")]
    items = [("commit", "Commits", d and f"{d['commits']:,}"), ("repo", "Repositories", d and str(d["repos"])),
             ("star", "Stars earned", d and str(d["stars"])), ("users", "Followers", d and str(d["followers"])),
             ("userplus", "Following", d and str(d["following"]))]
    cw = (700 - 44 - 4 * 10) / 5
    for i, (k, lab, val) in enumerate(items):
        x = 10 + 22 + i * (cw + 10); y = 60
        s += [f'<rect x="{x:.1f}" y="{y}" width="{cw:.1f}" height="72" rx="13" fill="{PANEL2}" stroke="{BORDER}" stroke-opacity=".65"/>',
              ic(k, x + 20, y + 21, CYAN, .95), text(lab, "R", 12.5, x + 38, y + 26, MUTED), text(val or dash, "B", 26, x + 15, y + 60, TXT)]
    o.append(panel(10, 10, 700, 140, 0, "".join(s)))
    # ================= Streak
    px = 720; pw = 370
    k = [f'<g transform="translate({px+34},38)"><g class="fl"><g fill="#ff8a3d" filter="url(#glow)">{FLAME}</g></g></g>',
         text("Contribution Streak", "B", 17, px + 54, 44, TXT)]
    cols = [px + 22 + 55 + i * 110 for i in range(3)]
    for i in (1, 2):
        k.append(f'<line x1="{px+22+i*110}" y1="62" x2="{px+22+i*110}" y2="136" stroke="{BORDER}" stroke-width="1"/>')
    if d:
        si = streak_info(d["days"]); t = si["today"]
        vals = [(str(si["total"]), "Contributions", "Past 12 months", TXT),
                (str(si["cur"]), "Current Streak", rng(*si["cur_range"], t) if si["cur"] else "No active streak", CYAN),
                (str(si["best"]), "Longest Streak", rng(*si["best_range"], t), TXT)]
    else:
        vals = [(dash, "Contributions", "Past 12 months", TXT), (dash, "Current Streak", "unavailable", CYAN), (dash, "Longest Streak", "unavailable", TXT)]
    for (v, lab, sub, col), cx in zip(vals, cols):
        if lab == "Current Streak":
            k.append(f'<circle cx="{cx}" cy="90" r="25" fill="none" stroke="{CYAN}" stroke-width="3" opacity=".9" filter="url(#glow)"/>')
            k.append(text(v, "B", 24, cx, 99, TXT, "m"))
        else:
            k.append(text(v, "B", 26, cx, 99, TXT, "m"))
        k.append(text(lab, "M", 12, cx, 128, col, "m"))
        k.append(text(sub, "R", 10.5, cx, 144 - 4, MUTED, "m"))
    o.append(panel(px, 10, pw, 140, .12, "".join(k)))
    # ================= Languages
    y0 = 160; L = [f'<g transform="translate(40,{y0+30})">{ic("code", 0, 0, CYAN, 1.0)}</g>',
                   text("Most Used Languages", "B", 17, 62, y0 + 36, TXT),
                   text("by code size - public repositories", "R", 11.5, 10 + 1080 - 22, y0 + 35, MUTED, "e")]
    langs = d["langs"] if d else []
    L.append(f'<rect x="34" y="{y0+52}" width="1032" height="14" rx="7" fill="#0d1b38"/>')
    if langs:
        seg, x = [], 34
        for name, pct, col in langs:
            w = 1032 * pct / 100
            seg.append(f'<rect x="{x:.1f}" y="{y0+52}" width="{w+0.5:.1f}" height="14" fill="{col}"/>'); x += w
        L.append(f'<g clip-path="url(#barclip2)"><g class="gx">{"".join(seg)}</g></g>')
        lx, ly = 34, y0 + 92
        for name, pct, col in langs:
            label = f"{name} {pct:.1f}%"
            wd = measure(label, "R", 13.5) + 30
            if lx + wd > 1070: lx, ly = 34, ly + 24
            L.append(f'<circle cx="{lx+6}" cy="{ly-5}" r="6" fill="{col}"/>')
            L.append(text(label, "R", 13.5, lx + 20, ly, "#d8e4f6")); lx += wd + 14
    else:
        L.append(text("No language data yet" if d else "data unavailable", "R", 13.5, 34, y0 + 92, MUTED))
    o.append(panel(10, y0, 1080, 114 + 6, .24, "".join(L)))
    o.append("</svg>")
    svg = "\n".join(o).replace('clip-path="url(#barclip2)"', f'clip-path="url(#barclip)"')
    return svg.replace('<clipPath id="barclip"><rect x="34" y="62" width="1032" height="14" rx="7"/></clipPath>',
                       f'<clipPath id="barclip"><rect x="34" y="{160+52}" width="1032" height="14" rx="7"/></clipPath>')

def main():
    if "--mock" in sys.argv:
        Path(sys.argv[sys.argv.index("--mock") + 1]).write_text(render(mock())); print("mock written"); return
    if "--empty" in sys.argv:
        OUT.parent.mkdir(exist_ok=True); OUT.write_text(render(None)); print("placeholder written"); return
    try:
        data = fetch()
    except Exception as e:
        print("FETCH FAILED:", e)
        if OUT.exists(): print("keeping previous file"); return
        OUT.parent.mkdir(exist_ok=True); OUT.write_text(render(None)); return
    OUT.parent.mkdir(exist_ok=True); OUT.write_text(render(data))
    print("stats-section.svg updated:", data["commits"], "commits,", len(data["langs"]), "languages")

if __name__ == "__main__":
    main()